import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        char[][] board = new char[9][9];

        for (int i = 0; i < 9; i++) {
            String line = br.readLine();
            if (line == null) break;
            StringTokenizer st = new StringTokenizer(line);
            for (int j = 0; j < 9; j++) {
                if (st.hasMoreTokens()) {
                    board[i][j] = st.nextToken().charAt(0);
                }
            }
        }

        System.out.println(isValidSudoku(board));
    }

    public static boolean isValidSudoku(char[][] board) {
        // Validate rows
        for (int i = 0; i < 9; i++) {
            if (!isValidGroup(board, i, 0, i, 8, 9)) {
                return false;
            }
        }

        // Validate columns
        for (int j = 0; j < 9; j++) {
            if (!isValidGroup(board, 0, j, 8, j, 9)) {
                return false;
            }
        }

        // Validate 3x3 sub-boxes
        for (int box = 0; box < 9; box++) {
            int startRow = (box / 3) * 3;
            int startCol = (box % 3) * 3;
            if (!isValidGroup(board, startRow, startCol, startRow + 2, startCol + 2, 9)) {
                return false;
            }
        }

        return true;
    }

    public static boolean isValidGroup(char[][] board, int r1, int c1, int r2, int c2, int n) {
        boolean[] seen = new boolean[n];
        for (int i = r1; i <= r2; i++) {
            for (int j = c1; j <= c2; j++) {
                char ch = board[i][j];
                if (ch != '.') {
                    int num = ch - '0';
                    if (seen[num]) {
                        return false;
                    }
                    seen[num] = true;
                }
            }
        }
        return true;
    }
}
